steps.code:
{% if customer.b2b? %}
  <p>Bem-vindo, comprador B2B!</p>
{% else %}
  <p>Compra no varejo</p>
{% endif %}

{% if customer.b2b? %}
  <p>
    Comprando por {{ customer.current_company.name }}
    — {{ customer.current_location.name }}
  </p>
{% endif %}

{% if customer.b2b? %}
  <p>Você está comprando para {{ customer.current_location.name }}</p>

  {% if customer.company_available_locations.size > 1 %}
    <ul>
      {% for location in customer.company_available_locations %}
        {% unless location.current? %}
          <li><a href="{{ location.url_to_set_as_current }}">{{ location.name }}</a></li>
        {% endunless %}
      {% endfor %}
    </ul>
  {% endif %}
{% endif %}

{% if customer.b2b? %}
  {{ product.price | money }}
{% else %}
  <a href="{{ routes.account_login_url }}">Entre para ver os preços</a>
{% endif %}

{% unless customer.b2b? %}
  {% form 'contact' %}
    <!-- formulário de pedido de cadastro B2B -->
  {% endform %}
{% endunless %}
